    "下载 PDF": "Télécharger le PDF",
    "国标麻将指国家体育总局在1998出台的《中国竞技麻将比赛规则(试行)》中确立的麻将规则": "Le mahjong MCR désigne les règles établies par les « Règles chinoises de compétition de mahjong (provisoires) », publiées en 1998 par l'Administration générale des sports de Chine.",
    "国标麻将（新编MCR）": "Mahjong MCR (MCR révisé)",
    "Natsuki 编著的《新编 MCR》。": "La nouvelle édition MCR, rédigée par Natsuki.",
    "国标麻将（小林改）": "Mahjong MCR (variante Xiaolin)",
    "社区修改的一种麻将规则": "Une variante des règles de mahjong créée par la communauté.",
    "K神麻将": "Mahjong K-shen",
    "国标K神改。": "Variante K-shen du MCR.",
    "立直麻将一般指日本麻将，是麻将规则的一个分支。": "Le mahjong Riichi désigne généralement le mahjong japonais, une branche des règles de mahjong.",
    "GGHK 立直麻将规则书": "Règles du mahjong riichi de la GGHK",
    "香港麻将协会发布的立直麻将规则书": "Règles du mahjong Riichi publiées par l'Association de mahjong de Hong Kong",
    "青雀是由莫莫柴编写的一款麻雀规则，旨在寻求一种在传统麻将行牌规则框架内的做大、抢和、兜牌防守三者平衡的麻雀游戏，同时试图为各类和牌提供基于美感和难度评估的赋分参照。": "Qingque est une règle de mahjong écrite par Momochai. Dans le cadre traditionnel du déroulement du mahjong, elle cherche un équilibre entre la construction de grandes mains, la recherche d'une victoire rapide et la défense, tout en proposant une référence de points pour les différentes mains gagnantes selon leur esthétique et leur difficulté.",
    "青雀一页纸": "Qingque en une page",
    "一页纸番种速记。": "Aide-mémoire des combinaisons en une page.",
    "青雀第十四版一页纸，来自 mmcr.online。": "Qingque, 14e édition, en une page, provenant de mmcr.online.",
    "青雀牌例第三版第一次修订，适用于第十四版，来自 mmcr.online。": "Exemples Qingque, première révision de la troisième édition, pour la 14e édition des règles, provenant de mmcr.online.",
    "青雀第十四版第一次修订，来自 mmcr.online。": "Qingque, première révision de la 14e édition, provenant de mmcr.online.",
    "青雀牌例": "Exemples de mains Qingque",
    "记录规则中所有番种对应的详解及牌例。": "Explications détaillées et exemples de toutes les combinaisons des règles.",
    "青雀规则文档": "Documentation des règles Qingque",
    "包含青雀规则的行牌逻辑和概念解释。": "Déroulement du jeu et explication des concepts de Qingque.",
    "MIL比赛规则。": "Règles de compétition MIL.",
    "四川麻将（SBR）竞赛规则": "Règles de compétition du mahjong du Sichuan (SBR)",
    "四川麻将（SBR）竞赛规则（试行 2025 版）。": "Règles de compétition du mahjong du Sichuan (SBR), édition provisoire 2025.",
    "长沙麻将是湖南地区流行的麻将玩法。": "Le mahjong de Changsha est une variante populaire dans le Hunan.",
    "长沙麻将（双鸟）规则书": "Règles du mahjong de Changsha à deux oiseaux",
    "本平台长沙麻将的规则说明（0709 更新）。": "Règles du mahjong de Changsha sur cette plateforme (mise à jour 0709).",
    "采用 144 张牌与 16 张手牌，并以台数结算的台湾麻将规则。": "Règles du mahjong taïwanais utilisant 144 tuiles, une main de 16 tuiles et un décompte en tai.",
    "台湾麻将台数表": "Barème des tai du mahjong taïwanais",
    "本平台台湾麻将采用的台数参考表。": "Barème de référence des tai utilisé pour le mahjong taïwanais sur cette plateforme.",
    "十样锦麻将": "Mahjong Shiyangjin",
    "尚未实装该规则，此处仅提供规则书查阅。": "Ces règles ne sont pas encore disponibles dans le jeu ; leur règlement est proposé ici uniquement pour consultation.",
    "十样锦麻将规则书": "Règles du mahjong Shiyangjin",
    "十样锦麻将规则说明。": "Explication des règles du mahjong Shiyangjin.",
    "本规则为根据《绘图麻雀牌谱》《想定宁波规则》等书籍文献资料汇总而成的，试图还原1920年代左右或以前的早期麻将样貌的麻将规则。相比现代规则，古典麻雀有番种体系简单、重刻杠幺九、未和牌家计分等特点，具有独特风味。": "Ces règles sont une synthèse de livres et de documents, dont « Relevés illustrés de mahjong » et « Proposition de règles de Ningbo », visant à restituer le mahjong des années 1920 environ ou d'avant. Par rapport aux règles modernes, le mahjong classique se distingue par un système de combinaisons simple, l'importance des pungs et des kongs d'extrémités et d'honneurs, et le décompte des points des joueurs qui n'ont pas gagné.",
    "平台现行的古典麻将版本。": "Version actuelle du mahjong classique utilisée sur la plateforme.",
    "■ 比赛列表": "■ Liste des compétitions",
    "比赛 - salasasa.cn": "Compétitions - salasasa.cn",
    "13 张直接显示听牌与进张，14 张显示切牌分析（副露按等价张数计算）。输入为空时将随机生成示例。": "Avec 13 tuiles, les attentes et les tuiles utiles s'affichent directement ; avec 14 tuiles, l'analyse des écarts s'affiche. Les groupes exposés comptent pour leur nombre équivalent de tuiles. Si le champ est vide, un exemple aléatoire est généré.",
