    "选择 14 张牌（含右侧和牌张）、副露与和牌方式，自动计算番种、得分以及全部和牌拆解形态。": "Sélectionnez 14 tuiles (dont la tuile gagnante à droite), les groupes exposés et le mode de victoire pour calculer automatiquement les combinaisons, le score et toutes les décompositions gagnantes.",
    "如 11122333m44455p66z + 和牌张": "Ex. : 11122333m44455p66z + tuile gagnante",
