    "计算得分": "Calculer le score",
    "查看全部拆解": "Toutes les décompositions",
    "国标计算器 - salasasa.cn": "Calculateur MCR - salasasa.cn",
    "对局开始前服务器公布承诺值 = SHA256(主种子 + 盐值)，对局结束后公布主种子与盐值。 在此本地复现随机座位与每局配牌，验证服务器未中途更换种子。计算均在浏览器内完成。": "Avant la partie, le serveur publie un engagement = SHA256(graine principale + sel). Après la partie, il révèle la graine principale et le sel. Reproduisez ici, localement, les places aléatoires et la distribution de chaque donne pour vérifier que le serveur n'a pas changé de graine en cours de partie. Tous les calculs sont effectués dans le navigateur.",
    "赤宝牌（与对局设置一致）": "Dora rouges (selon les paramètres de la partie)",
    "对局局数": "Nombre de donnes",
    "本场实际打的局数；立直 / 古典的连庄也算一局（局种子序号递增）": "Nombre de donnes effectivement jouées ; les maintiens du donneur en Riichi et en mahjong classique comptent aussi comme une donne (l'indice de graine augmente).",
    "牌谱 player_entry_order 的顺序，留空则用 玩家1-4": "Ordre de player_entry_order dans le relevé ; laisser vide pour utiliser Joueur 1–4",
    "承诺值（选填）": "Engagement (facultatif)",
    "开始验证": "Vérifier",
    "对局结束时公布的随机主种子（十六进制或十进制）": "Graine aléatoire principale révélée à la fin de la partie (hexadécimale ou décimale)",
    "玩家1": "Joueur 1",
    "玩家2": "Joueur 2",
    "玩家3": "Joueur 3",
    "玩家4": "Joueur 4",
    "可直接粘贴游戏内复制的「承诺值：xxxx 盐值：xxxx」": "Vous pouvez coller directement « Engagement : xxxx Sel : xxxx », copié depuis le jeu.",
    "随机种子验证 - salasasa.cn": "Vérification de la graine aléatoire - salasasa.cn",
    "手牌 0/13 或 14": "Main 0/13 ou 14",
    "0/13 或 14": "0/13 ou 14",
    "牌谱格式转换": "Conversion d'enregistrements",
    "浏览器本地转换，支持国标：雀渣 ↔ salasasa ↔ Botzone；日麻：salasasa ↔ MJAI。 反向重建（尤其 Botzone→salasasa、salasasa→雀渣）在隐藏信息处为近似，请核对后再用于训练。": "Conversion locale dans le navigateur. MCR : Quezha ↔ salasasa ↔ Botzone ; Riichi : salasasa ↔ MJAI. La reconstruction inverse (notamment Botzone→salasasa et salasasa→Quezha) est approximative pour les informations cachées ; vérifiez le résultat avant de l'utiliser pour l'entraînement.",
    "转换方向": "Sens de conversion",
    "雀渣 → salasasa（国标）": "Quezha → salasasa (MCR)",
    "salasasa → 雀渣（国标）": "salasasa → Quezha (MCR)",
    "salasasa → Botzone（国标）": "salasasa → Botzone (MCR)",
    "Botzone → salasasa（国标）": "Botzone → salasasa (MCR)",
    "salasasa → MJAI（日麻）": "salasasa → MJAI (Riichi)",
    "MJAI → salasasa（日麻）": "MJAI → salasasa (Riichi)",
    "粘贴雀渣 raw（含 script）/ 解码 step / session+records JSON。": "Collez le raw Quezha (avec script), les step décodés ou le JSON session+records.",
    "可靠程度：完整（推荐）": "Fiabilité : complète (recommandé)",
    "字段 / 内容\t结果\t怎么处理\t例子": "Champ / contenu\tRésultat\tTraitement\tExemple",
    "手牌 / 牌山 / 摸切吃碰杠和\t完整\t按雀渣网页脚本位域原样解码，不猜测。": "Main / mur / pioche, écart, chow, pung, kong, victoire\tComplet\tDécodage exact des champs de bits du script web Quezha, sans supposition.",
    "摸 1 万 → [\"d\", 11]；手切 3 饼 → [\"c\", 23, \"F\"]": "Pioche du 1 de caractères → [\"d\", 11] ; écart du 3 de cercles depuis la main → [\"c\", 23, \"F\"]",
    "番种 y → hu_fan\t完整\t用网页 FAN[] 表把番种编号还原成中文名。": "Combinaison y → hu_fan\tComplet\tLa table FAN[] de la page restitue les noms chinois à partir des numéros de combinaisons.",
    "索引 51 → \"混一色\"；花牌×2 → \"花牌*2\"": "Indice 51 → \"混一色\" ; fleurs×2 → \"花牌*2\"",
    "p0_uid … p3_uid\t近似\t雀渣玩家 id 是短字符串，salasasa 要整数，用字符串稳定哈希生成占位 uid。": "p0_uid … p3_uid\tApproximatif\tLes ID des joueurs Quezha sont de courtes chaînes ; salasasa exige des entiers. Un hachage stable des chaînes génère des UID de remplacement.",
    "雀渣 \"pm6Eet01\" → p0_uid: 955674184（不是真实 salasasa 账号）": "Quezha \"pm6Eet01\" → p0_uid: 955674184 (ce n'est pas un véritable compte salasasa)",
