    "多规则同台：国标、立直、青雀、四川麻将、长沙麻将等，规则书与牌例可在站内查阅。": "Plusieurs règles sur une même plateforme : MCR, Riichi, Qingque, mahjong du Sichuan, mahjong de Changsha, etc. Les règles et exemples de mains sont consultables sur le site.",
    "开源可自建：项目遵循 MIT，可自行部署服务器；公共平台若因攻击等原因无法维持，规则制定者仍可自建服务。": "Code ouvert et hébergement autonome : le projet est sous licence MIT et vous pouvez déployer votre propre serveur. Si des attaques ou d'autres causes empêchent le maintien de la plateforme publique, les auteurs des règles peuvent toujours héberger leur service.",
    "当前默认配置：": "Réglages par défaut :",
    "鸣牌保护时间：1.3s": "Délai de protection des appels : 1,3 s",
    "第一追赶时间：0.7s": "Premier délai de rattrapage : 0,7 s",
    "第二追赶时间：0.5s": "Second délai de rattrapage : 0,5 s",
    "房间配置中可开关战术鸣牌。关闭时走「等待最高优先级操作执行完成」的原始流程。": "Les appels tactiques peuvent être activés ou désactivés dans les paramètres de la salle. S'ils sont désactivés, le déroulement initial s'applique : attendre la fin de l'action de priorité la plus élevée.",
