    "数字 UID": "UID numérique",
    "网麻战绩（可选）": "Résultats de mahjong en ligne, si disponibles",
    "赞助可联系群主Xe，赞助者在数据站可以额外获得下载牌谱的限额，也可以提前准入中级场，赞助100元添加鸣谢名单": "Pour soutenir la plateforme, contactez Xe. Les donateurs bénéficient d'un quota supplémentaire de téléchargement de parties dans les données et peuvent accéder plus tôt aux tables intermédiaires. Un don de 100 yuans permet de figurer dans les remerciements.",
