    "初始 1000 分，仅系统匹配计分，自建房不计。": "Le score initial est de 1000. Seul le matchmaking compte ; les salles créées par les joueurs sont exclues.",
    "K 值为 32：胜者加分与败者扣分数值相同。": "K vaut 32 : le gagnant gagne autant de points que le perdant en perd.",
    "战胜高分玩家加分更多，战胜低分玩家加分更少；反之亦然。": "Battre un joueur mieux classé rapporte plus de points ; battre un joueur moins bien classé en rapporte moins. L'inverse s'applique aux défaites.",
    "计算式：变化值 = 32 ×（实际结果 − 预期胜率），结果四舍五入。": "Formule : variation = 32 × (résultat réel − probabilité de victoire attendue), arrondie à l'entier le plus proche.",
