    "赛事用于限时比赛；基地用于长期活动室。两者并列，审批通过后申请人成为主管理员。": "Les compétitions sont limitées dans le temps ; les clubs sont des espaces d'activité durables. Les deux sont indépendants. Après approbation, le demandeur en devient l'administrateur principal.",
