    "发布比赛公告说明": "Consignes de publication des annonces",
    "您在包括且不限于以下情形时都可以发布比赛公告，并且您应该在1、4条所属情形发生时发布比赛公告，本平台对此不做严格规定。": "Vous pouvez publier une annonce notamment dans les situations ci-dessous. Vous devriez le faire dans les cas 1 et 4, sans obligation stricte imposée par la plateforme.",
