    "赛事注册成功，在比赛开赛时可点击开始赛事按钮，开启赛事以后可开始创建比赛房间": "Compétition enregistrée. À son début, cliquez sur « Démarrer la compétition » ; vous pourrez alors créer des salles de compétition.",
    "赛事已开启，在比赛全程结束后可点击关闭赛事按钮结束赛事，在关闭结束后仍可以查看赛事数据对赛事内容进行统计或查询。": "La compétition est ouverte. À la fin de l'ensemble de l'événement, cliquez sur « Fermer la compétition ». Les données resteront consultables pour les statistiques et les recherches.",
