    "扣减分逻辑": "Calcul des pertes de PT",
    "第三名扣除“段位均失 PT × 0.3 × 局制系数”，第四名扣除“段位均失 PT × 0.7 × 局制系数”。东风 0.49、半庄 0.7、全庄 1。": "La 3e place perd les PT de perte moyenne du rang × 0,3 × coefficient du format. La 4e place perd les PT de perte moyenne du rang × 0,7 × coefficient du format. Tour Est : 0,49 ; deux tours : 0,7 ; quatre tours : 1.",
