    "Salasasa七段及以上或职业五段及以上并实名注册": "7e dan Salasasa et plus, ou 5e dan professionnel et plus, avec inscription sous son vrai nom",
    "10级－3级": "Du 10e au 3e kyu",
    "国标十六张：扩展规则与牌例": "MCR à 16 tuiles : règles étendues et exemples",
    "以新编 MCR 为底本的本站十六张扩展，含逐番适用表与五面子计分补则。": "L’extension à 16 tuiles du MCR révisé proposée par cette plateforme, avec un tableau des combinaisons applicables et des règles de calcul supplémentaires pour cinq groupes.",
    "四人立直麻将，支持多种规则预设及役种、计分和流局设置": "Mahjong riichi à quatre joueurs, avec plusieurs préréglages et des options pour les yaku, le calcul des points et les donnes nulles.",
    "香港麻将协会发布的立直麻将规则书。": "Règles du mahjong riichi publiées par l’association de mahjong de Hong Kong.",
    "全国雀庄公式战手册 v1.0": "Manuel national des matchs officiels en salles de mahjong v1.0",
    "雀庄公式战预设所依据的公开手册。": "Manuel public servant de référence au préréglage des matchs officiels en salles de mahjong.",
    "查看公开手册": "Lire le manuel public",
    "台湾麻将：使用144张牌与16张手牌，按台计分，支持公开报听、食替限制与八仙过海等规则。具体流程与台表可在馆规设置中选择。": "Le mahjong taïwanais utilise 144 tuiles et une main de 16 tuiles, avec un décompte en tai. Il propose la déclaration publique d'une main en attente, des restrictions sur les appels de substitution et la règle des Huit Immortels Traversant la Mer. Le déroulement et le barème des tai se choisissent dans les paramètres des règles de table.",
    "四川麻将（血战到底）": "Mahjong du Sichuan (Combat sanglant jusqu'au bout)",
    "长沙麻将经典双鸟规则：108张数牌，可吃上家牌，258将小胡，大胡可叠加，和牌后翻两只鸟并按座位中鸟加倍。": "Règles classiques de Changsha à deux oiseaux : 108 tuiles de couleur ; le Chow est autorisé sur la défausse du joueur de gauche. Une petite main exige une paire de 2, de 5 ou de 8 ; les grandes mains sont cumulables. Après une victoire, deux tuiles oiseaux sont révélées et les points sont doublés selon les sièges touchés.",
    "本平台长沙麻将规则说明。": "Règles du mahjong de Changsha utilisées sur cette plateforme.",
    "也叫 MCR、中国麻将竞赛规则": "Également appelé MCR ou règles chinoises de compétition de mahjong",
    "计分": "Calcul des points",
    "← 馆藏目录": "← Catalogue de la bibliothèque",
    "返回馆藏目录": "Retour au catalogue",
    "谱系沿革": "Histoire et filiation",
    "形成时间待证": "Date d’origine non établie",
    "地方规则与未定年线索": "Règles régionales et indices non datés",
    "多版／平台伞称（1998原本另列）": "Terme regroupant plusieurs éditions et plateformes (édition de 1998 répertoriée séparément)",
    "国标麻将规则资料，包含 Natsuki 编著的《新编 MCR》及各改编版本规则书。": "Documentation des règles MCR, dont la nouvelle édition de Natsuki et les règles de variantes adaptées.",
    "国标是多版规则及平台实现的伞称。1998原本题署7月、9月初版；WMO 2006和赛事补充须另看具名版本。平台使用的新编MCR不应与1998全文等同，原目录11月出台说已按原书更正。": "MCR désigne plusieurs éditions des règles et leurs implémentations. Le texte original de 1998 est daté de juillet, avec une première impression en septembre. Les règles WMO de 2006 et les compléments de compétition constituent des éditions distinctes. La nouvelle édition MCR utilisée sur cette plateforme ne se confond pas avec le texte intégral de 1998. L’ancienne date de novembre indiquée dans le catalogue a été corrigée d’après le livre original.",
    "国标麻将（新编 MCR）": "MCR — nouvelle édition",
