    "副露用括号编码并区分大小写：": "Les codes de groupe sont entre parenthèses et sensibles à la casse :",
    "为二三四万明顺，": "désigne un chow exposé 2-3-4 de caractères,",
    "为三饼暗刻；编码中的数字为项目牌号。": "désigne un pung caché de 3 cercles ; les nombres sont les identifiants de tuile du projet.",
    "表示明顺 / 暗顺（数字取顺子中间牌）；": "désigne un chow exposé / caché (identifiant de la tuile centrale) ;",
