    "表示明杠 / 暗杠。": "désigne un kong exposé / caché.",
    "项目牌号：11–19 万、21–29 饼、31–39 条、41–44 东南西北、45 中、46 白、47 发；与": "Identifiants : 11–19 caractères, 21–29 cercles, 31–39 bambous, 41–44 Est/Sud/Ouest/Nord, 45 rouge, 46 blanc, 47 vert ; l’ordre diffère de",
    "简写顺序不同。": "la notation.",
    "例如": "Par exemple",
    "后为单张和牌张。副露与简写双向同步，删除括号编码也会移除对应副露。": "est suivi d’une seule tuile gagnante. Les groupes et la notation sont synchronisés ; supprimer un code retire aussi le groupe correspondant.",
    "■ 麻雀计算器与猜番": "■ Calculateur de mahjong et quiz de combinaisons",
    "分析向听、进张与切牌，并计算和牌番种、得分及全部拆解。": "Analysez le shanten, les tuiles utiles et les défausses, puis calculez les combinaisons, les scores et toutes les décompositions gagnantes.",
    "：万子，数字 1–9 表示一至九万；": ": caractères, les chiffres 1–9 désignent les tuiles 1 à 9 ;",
    "表示赤五万（5m 的红宝牌写法）。": "désigne le 5 rouge de caractères (notation du 5m rouge).",
    "：饼（筒）子；": ": cercles ;",
    "：条（索）子；写法同万子。": ": bambous, avec la même notation que les caractères.",
    "：字牌，数字 1–7 依次为": ": honneurs, les chiffres 1–7 désignent dans l'ordre",
