    "<color=#05B852>状态：进行中</color>\n开始时间：2026-07-15\n结束时间：未定\n<color=#E6B814>资格：未报名</color>\n<color=#E6B814>自动通过报名：否</color>\n<color=#E6B814>允许未报名玩家创建房间：否</color>\n<color=#E6B814>允许未报名玩家进入队列：否</color>": "<color=#05B852>État : en cours</color>\nDébut : 2026-07-15\nFin : à déterminer\n<color=#E6B814>Inscription : non inscrit</color>\n<color=#E6B814>Approbation automatique des inscriptions : non</color>\n<color=#E6B814>Création de salles par les non-inscrits : non</color>\n<color=#E6B814>File d'attente accessible aux non-inscrits : non</color>",
