    "我想添加自己的麻将规则\n(点击这里)": "Je souhaite ajouter mes règles de mahjong\n(cliquer ici)",
    "北京麻将（吃碰提）是北京地区的民间麻将规则，其特点为有字牌、无花牌、有万能牌、非门前清状态不可点和，番种体系较为简单。本文参考网络资料与线下实践梳理北京麻将的基本玩法，体现北京麻将核心特征，便于各地麻将爱好者了解北京麻将主要框架。": "Le mahjong de Pékin (Chi Peng Ti) est une règle populaire de la région de Pékin. Il comporte des honneurs et des jokers, mais pas de fleurs ; une main ouverte ne peut pas gagner sur écart et le système de combinaisons est relativement simple. Ce texte présente les bases à partir de sources en ligne et de la pratique sur table, en dégageant ses caractéristiques principales pour permettre aux amateurs de découvrir son fonctionnement général.",
