    "  项目简介": "  Présentation du projet",
    "open_mahjong_unity是一款基于unity/python-fastapi的麻将平台项目，该项目遵循MIT许可协议、免费、开源、支持PC/安卓/ios三端互通；目标是支持所有麻将规则、并且提供给玩家自定义规则的选项。欢迎加入q群906497522参与讨论、协助和测试。": "open_mahjong_unity est une plateforme de mahjong fondée sur unity/python-fastapi, gratuite, ouverte et sous licence MIT. Elle permet de jouer ensemble sur PC, Android et iOS. Elle vise à prendre en charge toutes les règles de mahjong et à proposer des règles personnalisées. Rejoignez le groupe QQ 906497522 pour discuter, contribuer et tester.",
    "  随机种子": "  Graines aléatoires",
    "在玩家 A 出牌时，若玩家 B、C 可对该出牌进行操作，则 B、C 会提前看到这张出牌；玩家 D 则会延迟一个「鸣牌保护时间」才看到出牌。若在鸣牌保护时间内 B、C 对出牌进行了操作，玩家 D 会立刻看见出牌，并在「第一追赶时间」之后再看见 B、C 其一执行的鸣牌申请或鸣牌。\n\n由于玩家 D 必定延迟一个第一追赶时间才看见 B、C 其一的鸣牌，若 B、C 在吃碰后快速出牌，这张出牌在 D 的视角中会显得「即时」。因此平台在触发鸣牌保护后进行出牌时，会保证至少再经过「第二追赶时间」才播放动画，避免在 D 的视角中出牌紧贴在吃碰之后生效。\n\n当前默认配置：\n鸣牌保护时间：1.3s\n第一追赶时间：0.7s\n第二追赶时间：0.5s": "Quand A écarte une tuile sur laquelle B et C peuvent agir, B et C la voient en avance ; D ne la voit qu'après le « délai de protection des appels ». Si B ou C agit pendant ce délai, D voit immédiatement la tuile, puis, après le « premier délai de rattrapage », la demande d'appel ou l'appel de B ou C.\n\nComme D voit nécessairement l'appel de B ou C avec ce premier délai de retard, un écart rapide après le chow ou le pung peut lui sembler immédiat. Après le déclenchement de la protection, la plateforme attend donc au moins le « second délai de rattrapage » avant de jouer l'animation d'écart, pour que celui-ci ne suive pas immédiatement l'appel du point de vue de D.\n\nValeurs actuelles par défaut :\nProtection des appels : 1.3s\nPremier rattrapage : 0.7s\nSecond rattrapage : 0.5s",
    "战术鸣牌的设计来源于雀渣：在其他家申请鸣牌以后，可用更高优先级的操作打断他家更低优先级的操作，以模拟线下刻意「碰断吃」等战术。\n\n示例一：玩家 A 出牌 T，玩家 B 可吃、玩家 C 可碰。此时 C 选择跳过，但 B 点击了吃牌；由于仍存在可执行的更高优先级操作，系统会再次询问 C 是否要碰，以模拟国标线下允许刻意用碰打断别人吃的情形。\n\n示例二：玩家 A 出牌 T，玩家 B 可吃或和牌，玩家 C 可碰。B 选择吃，C 用碰打断了 B 的吃；此时 B 不再能用和去打断 C 的碰。这符合国标不允许玩家在鸣牌发声后更改自己要执行动作的规则。": "Les appels tactiques sont inspirés de Quezha : après une demande d'appel, une action de priorité supérieure peut interrompre une action de priorité inférieure, pour reproduire notamment l'interruption volontaire d'un chow par un pung sur table.\n\nExemple un : A écarte T, B peut faire chow et C peut faire pung. C passe, mais B choisit chow. Comme une action de priorité supérieure reste possible, le système demande à nouveau à C s'il veut faire pung, reproduisant la possibilité en MCR d'interrompre volontairement le chow d'un autre joueur.\n\nExemple deux : A écarte T, B peut faire chow ou gagner, et C peut faire pung. B choisit chow, puis C l'interrompt par pung. B ne peut alors plus interrompre ce pung par une victoire. Cela respecte la règle MCR qui interdit de changer d'action après l'annonce d'un appel.",
    "  添加规则": "  Ajouter des règles",
    "  相关链接": "  Liens utiles",
