    "手牌牌面背景：用于在手牌牌面使用透明通道的情况下替换背景，默认尺寸 272*389。\n手牌牌背：用于在里宝牌区或者2D展示中显示牌背\n3D牌面背景：用于在3D卡牌的正面叠底在3D花纹下显示\n上传成对 zip格式：hand-back.png + hand-bg.png。": "Fond des faces de la main : remplace le fond si les faces utilisent la transparence ; dimensions par défaut 272*389.\nDos des tuiles de la main : utilisé dans la zone des ura-dora ou en affichage 2D.\nFond des faces 3D : placé sous les motifs sur l'avant des tuiles 3D.\nZIP de la paire : hand-back.png + hand-bg.png.",
