    "普通入场段位": "Rang d'accès habituel",
    "C 为负数时是保护奖励；PT 保留两位小数。十段固定 100/100 PT，每场变动为 0。": "Un C négatif constitue une prime de protection ; les PT sont arrondis à deux décimales. Le 10e dan reste à 100/100 PT, avec une variation de 0 par partie.",
    "立直 · 段位升降与扣分表": "Riichi · Progression des rangs et déductions",
    "各名次扣相同的 C；东风整体乘 0.7，负数为保护奖励。特许可突破最低段位；— 为禁入场次。": "Le même C est déduit à chaque place ; le total est multiplié par 0.7 au tour Est. Une valeur négative est une prime de protection. Une dérogation permet de dépasser le rang minimal ; — indique un niveau interdit.",
