    "暂无物品": "Aucun objet",
    "装扮": "Personnalisation",
    "点击改名": "Cliquer pour changer de nom",
    "段位与匹配说明": "Rangs et appariement",
    "为适配不同人数的游玩规则的匹配机制，平台目前提供以下两种段位设计\n1.对于每日对于超过100局的麻将规则，使用以级段制为主的段位系统\n2.对于每日对局低于100局的麻将规则，使用以elo为主的匹配系统进行对局，待人数提升后，按照elo排名设计级段制段位，并通过elo对玩家的段位进行赋分\n3.对于娱乐、开发中或不需添加段位机制的规则，不开设段位匹配场": "Pour adapter l'appariement au nombre de joueurs de chaque règle, la plateforme propose actuellement les deux systèmes suivants :\n1. Pour les règles dépassant 100 parties quotidiennes, un système principalement fondé sur les kyu et les dan.\n2. Pour les règles sous 100 parties quotidiennes, un appariement principalement fondé sur l'Elo. Lorsque le nombre de joueurs augmente, les rangs kyu et dan sont conçus selon le classement Elo, qui sert à attribuer les points de rang.\n3. Les règles de détente, en développement ou ne nécessitant pas de rang n'ont pas de salles classées.",
    "Elo 匹配\n\n各规则独立计分。虹雀可选半庄8局或全庄16局，川麻血战和血流换三张为半庄战（8副）。按加入顺序匹配，满四人立即进入对局。\n初始 R = 1500，分母 2400。虹雀半庄 K=16，全庄 K=32；川麻 K=32。按最终名次比较三个对手，并列算平局。桌均 R 低于 1500 时追加保护，不设个人保底。\n\n青雀使用独立的局均素点算法，详见青雀页面。国标、立直仅结算段位/PT；自定义对局不计分。": "Appariement Elo\n\nChaque règle a ses propres points. Hongque propose deux tours (8 donnes) ou quatre tours (16 donnes) ; Combat sanglant et Flot de sang avec échange de trois tuiles se jouent en deux tours (8 donnes). Les joueurs sont appariés par ordre d'arrivée et la partie commence dès qu'ils sont quatre.\nR initial = 1500, dénominateur 2400. Pour Hongque, K=16 sur deux tours et K=32 sur quatre ; pour le Sichuan, K=32. La place finale est comparée à celles des trois adversaires ; les égalités comptent comme des matchs nuls. Une protection est ajoutée si le R moyen de la table est inférieur à 1500, sans minimum individuel.\n\nQingque utilise un calcul indépendant de points bruts moyens par donne, détaillé sur sa page. Le MCR et le Riichi ne comptent que les rangs/PT ; les parties personnalisées ne rapportent aucun point.",
    "放弃比赛": "Abandonner la partie",
    "检测到您有一场正在进行的游戏，是否返回游戏?": "Une partie en cours a été détectée. Voulez-vous y revenir ?",
    "刷新房间列表成功": "Liste des salles actualisée",
    "Elo 匹配\n\n青雀、虹雀、川麻血战、血流换三张独立计分。虹雀可选半庄8局或全庄16局，川麻血战和血流换三张为半庄战（8副），青雀为全庄战。按加入顺序匹配，满四人立即进入对局。\n初始 R = 1500，分母 2400。虹雀半庄 K=16，全庄 K=32，两种局制共用虹雀积分；其他 Elo 规则 K=32。按最终名次比较三个对手，并列算平局。桌均 R 低于 1500 时追加保护，不设个人保底。\n\n问号内显示算法。国标、立直仅结算段位/PT；自定义对局不计分。": "Appariement Elo\n\nQingque, Hongque, Combat sanglant du Sichuan et Flot de sang avec échange de trois tuiles ont leurs propres points. Hongque propose deux tours (8 donnes) ou quatre tours (16 donnes) ; les deux variantes du Sichuan se jouent en deux tours (8 donnes), Qingque en quatre tours. Les joueurs sont appariés par ordre d'arrivée et la partie commence dès qu'ils sont quatre.\nR initial = 1500, dénominateur 2400. Pour Hongque, K=16 sur deux tours et K=32 sur quatre, avec les mêmes points pour les deux formats ; les autres règles Elo utilisent K=32. La place finale est comparée à celles des trois adversaires ; les égalités comptent comme des matchs nuls. Une protection est ajoutée si le R moyen de la table est inférieur à 1500, sans minimum individuel.\n\nLe point d'interrogation présente le calcul. Le MCR et le Riichi ne comptent que les rangs/PT ; les parties personnalisées ne rapportent aucun point.",
