    "把牌先分成三类：数牌、字牌、花牌。\n不用急着记番种，今天先认清牌面。": "Commençons par trois catégories : les tuiles numérotées, les honneurs et les fleurs.\nPas besoin de retenir les combinaisons tout de suite ; aujourd'hui, découvrons les faces.",
