    "琪露诺": "Cirno",
    "欢迎来到麻雀教室！我是琪露诺。先一起认识麻将牌吧——数牌 108 张，字牌 28 张，再加 8 张花牌。": "Bienvenue dans la classe de mahjong ! Je suis Cirno. Découvrons ensemble les tuiles : 108 tuiles numérotées, 28 honneurs et 8 fleurs.",
