    "返回修改": "Revenir aux modifications",
    "<b>青雀 · 局均素点 Elo</b>\n初始 R = 1500；全庄与无固定时限共用积分。\nN = 实际完成局数（包含流局），Y = 累计净素点。\n局均 A = Y / N；桌均 M = 四人 R 的平均值。\n预期局均 = (自己 R - M) / 32\n普通变化 = 32N / (N + 1584) × (A - 预期局均)\n不按名次计分，不设涨跌硬上限。\n保护系数 K = 3200N / (N + 1584)\nT = max(0, 1500 - M)\nE = 1 / (1 + 10^((对手 R - 自己 R) / 2400))\nE' = 1 / (1 + 10^((对手 R + T - 自己 R) / 2400))\n指数限制在 -16 至 16；合计为三个对手之和。\n保护奖励 = (K / 3) × 合计(E - E')\n新 R = 原 R + 普通变化 + 保护奖励。\n普通变化按分币分配余差保持零和，保护另取两位。\n同为1500分、16局：净赢800加16，1600加32。\n未完成局不计入；零完成局不结算。": "<b>Qingque · Elo des points bruts moyens par donne</b>\nR initial = 1500 ; les formats quatre tours et sans limite de durée partagent les points.\nN = donnes terminées (donnes nulles incluses), Y = cumul net des points bruts.\nMoyenne par donne A = Y / N ; moyenne de table M = moyenne des R des quatre joueurs.\nMoyenne attendue par donne = (son R - M) / 32\nVariation normale = 32N / (N + 1584) × (A - moyenne attendue)\nSans calcul selon la place ni plafond fixe de variation.\nCoefficient de protection K = 3200N / (N + 1584)\nT = max(0, 1500 - M)\nE = 1 / (1 + 10^((R adverse - son R) / 2400))\nE' = 1 / (1 + 10^((R adverse + T - son R) / 2400))\nExposant limité de -16 à 16 ; somme sur les trois adversaires.\nPrime de protection = (K / 3) × somme(E - E')\nNouveau R = ancien R + variation normale + prime de protection.\nLes écarts d'arrondi des variations normales sont répartis au centième pour conserver une somme nulle ; la protection est arrondie séparément à deux décimales.\nTous à 1500 points, sur 16 donnes : un gain net de 800 rapporte 16, de 1600 rapporte 32.\nLes donnes inachevées sont exclues ; aucun calcul si aucune donne n'est terminée.",
    "麻雀教室": "Classe de mahjong",
