    "调整所有声音的总体音量。": "Régler le volume général de tous les sons.",
    "调整背景音乐的音量。": "Régler le volume de la musique de fond.",
    "调整操作与对局音效的音量。": "Régler le volume des effets de commandes et de partie.",
