    "设置和牌时是否播放锣声音效。": "Activer ou désactiver le gong lors d'une victoire.",
    "设置匹配成功时是否播放提示音。": "Activer ou désactiver le son lorsqu'une partie est trouvée.",
    "选择摸切的鼠标快捷操作，或关闭快捷操作。": "Choisir ou désactiver le raccourci souris pour écarter la tuile piochée.",
    "选择取消响应的鼠标快捷操作，或关闭快捷操作。": "Choisir ou désactiver le raccourci souris pour passer.",
    "开启后先选中手牌，再次点击确认出牌。": "Sélectionner d'abord une tuile, puis cliquer à nouveau pour confirmer l'écart.",
    "设置进入对局时是否默认开启自动补花。": "Activer par défaut le remplacement automatique des fleurs à l'entrée en partie.",
    "在规则允许时显示强制过操作。": "Afficher l'action de passage forcé lorsque les règles le permettent.",
    "隐藏聊天，并遮蔽房间信息与其他玩家昵称。": "Masquer la discussion, les informations de salle et les pseudonymes des autres joueurs.",
    "选择实时观战申请的处理方式：询问、自动同意或自动拒绝。": "Choisir le traitement des demandes d'observation en direct : demander, accepter ou refuser automatiquement.",
    "手牌示例随当前花色、字牌和三元牌顺序调整。": "L'exemple de main suit l'ordre actuel des familles, des honneurs et des dragons.",
    "非日麻规则下的三元牌排列示例。": "Exemple d'ordre des dragons hors Riichi.",
    "日麻规则下的三元牌排列示例。": "Exemple d'ordre des dragons en Riichi.",
    "调整万、索、饼的排列顺序，下方手牌同步预览。": "Modifier l'ordre des caractères, bambous et cercles ; la main ci-dessous affiche le résultat.",
    "调整字牌与数牌的先后顺序，下方手牌同步预览。": "Modifier l'ordre des honneurs et des tuiles numérotées ; la main ci-dessous affiche le résultat.",
    "调整非日麻规则下中、发、白的排列顺序。": "Modifier l'ordre des dragons rouge, vert et blanc hors Riichi.",
    "调整日麻规则下中、发、白的排列顺序。": "Modifier l'ordre des dragons rouge, vert et blanc en Riichi.",
    "切换白板牌面的纯白或回形样式。": "Choisir un dragon blanc uni ou encadré.",
    "设置对局操作按钮是否使用分类颜色。": "Utiliser ou non des couleurs par catégorie pour les boutons d'action.",
    "3D 牌描边使用标准样式。": "Utiliser le contour standard des tuiles 3D.",
    "设置副露牌组之间是否留出间距；规则要求时固定开启。": "Laisser ou non un espace entre les groupes exposés ; ce réglage est imposé si les règles l'exigent.",
    "切换游戏界面的显示语言。": "Changer la langue de l'interface du jeu.",
    "设置画面帧率上限；开启垂直同步时由同步设置决定。": "Définir la limite d'images par seconde ; la synchronisation verticale prévaut lorsqu'elle est activée.",
    "让画面刷新与显示器同步，减少画面撕裂。": "Synchroniser l'image avec l'écran pour réduire les déchirures.",
    "当前规则固定开启副露间距。": "Les règles actuelles imposent l'espacement des groupes exposés.",
    "原版修整": "Original retouché",
