    "和牌由花色各不相同的牌构成。": "Toutes les tuiles de la main sont de couleurs différentes.",
    "全彩": "Toutes les couleurs",
    "和牌由花色各不相同的牌构成且含有所有全色及半色。 不计光谱。": "Toutes les tuiles sont de couleurs différentes et toutes les couleurs pleines et demi-couleurs sont présentes. Ne compte pas Spectre.",
    "清一数": "Une seule valeur",
    "仅由一种数牌构成的和牌。 不计碰碰和。": "La main ne contient qu'un seul numéro. Ne compte pas Tout Pung.",
    "仅由二种数牌构成的和牌。 不计碰碰和。": "La main ne contient que deux numéros. Ne compte pas Tout Pung.",
    "三数": "Trois valeurs",
    "仅由三种相同间隔的数牌构成的和牌。": "La main ne contient que trois numéros à intervalles égaux.",
    "四数": "Quatre valeurs",
