    "全场次": "Tous les niveaux",
    "暂无公开对局记录": "Aucune partie publique enregistrée",
    "自定义房间\n暂未提供公共牌谱列表": "Salles personnalisées\nListe des relevés publics pas encore disponible",
    "自定义房间暂未提供每日汇总": "Les salles personnalisées n'ont pas encore de synthèse quotidienne",
