    "单日峰值  ": "Maximum quotidien  ",
    "暂无日汇总": "Aucune synthèse quotidienne",
    " · 累计统计": " · Statistiques cumulées",
    " · 近期公开牌谱": " · Relevés publics récents",
    "近期对局 · ": "Parties récentes · ",
    " · 番种记录": " · Historique des combinaisons",
    "日汇总截止 ": "Synthèse quotidienne jusqu'au ",
    "平台累计\n按当前规则及场次读取公开牌谱统计，对局按 game_id 去重。全场次含匹配、自定义和赛事；四张场次卡始终展示当前规则的累计数量。\n\n匹配场行为数据\n累计手数为全桌手数；平均和牌 = 总和牌番值 ÷ 和牌次数；自摸占和牌 = 自摸次数 ÷ 和牌次数。不展示个人胜率和个人顺位。\n\n每日对局量\n时间窗口只作用于日汇总，不改变累计指标与最近牌谱。统计日以北京时间 04:00 切日，截止最近已完成聚合日。缺少记录的日期留空，不补零。\n\n场次与局制\n初级、中级、高级、自定义的累计计数来自网站首页的原始牌谱归口接口。自定义部分缺少完整行为指标，只展示已提供的对局计数。\n\n最近对局\n全场次时展示匹配场公共牌谱，可按等级场筛选、翻页并查看同桌结算。赛事单独查询；现有接口未提供自定义房间公共牌谱列表。\n\n番种记录\n累计出现次数可重复，不是互斥占比。所选场次无支持时显示不可用。": "Cumul de la plateforme\nStatistiques des relevés publics selon les règles et le niveau choisis, avec dédoublonnage par game_id. Tous les niveaux comprennent les parties classées, personnalisées et les compétitions ; les quatre cartes de niveaux affichent toujours leurs totaux pour les règles actuelles.\n\nComportements en parties classées\nLe nombre de mains cumule toute la table ; valeur moyenne des victoires = total des fans gagnants ÷ nombre de victoires ; part des victoires sur pioche = victoires sur pioche ÷ victoires. Aucun taux de victoire ni classement individuel n'est affiché.\n\nVolume quotidien\nLa période n'affecte que la synthèse quotidienne, pas les totaux ni les relevés récents. La journée statistique commence à 04:00, heure de Pékin, jusqu'à la dernière journée agrégée complète. Les dates sans données restent vides, sans zéro ajouté.\n\nNiveaux et formats\nLes totaux débutant, intermédiaire, avancé et personnalisé proviennent de l'interface de relevés de l'accueil du site. Faute d'indicateurs complets pour les parties personnalisées, seuls les nombres fournis sont affichés.\n\nParties récentes\nAvec tous les niveaux, les relevés publics classés sont affichés ; vous pouvez filtrer par niveau, changer de page et consulter les résultats de la table. Les compétitions se consultent séparément ; l'interface actuelle ne fournit pas la liste publique des salles personnalisées.\n\nCombinaisons\nLes occurrences cumulées peuvent se chevaucher ; leurs proportions ne sont pas exclusives. Si le niveau choisi n'est pas pris en charge, l'indisponibilité est indiquée.",
    "符": "fu",
    "台": "tai",
    "点": "points",
    " 局": " donnes",
    "已解析 ": "Analysées ",
    " 场": " parties",
    "本规则暂未提供逐局统计": "Ces règles n'ont pas encore de statistiques par donne",
    "统计范围\n所选规则、房间类型与日期同时作用于战绩和对局列表。\n\n和牌率 / 放铳率\n个人和牌次数 / 放铳次数 ÷ 参与的手数。\n\n自摸占和牌\n自摸次数 ÷ 和牌次数；不是每手自摸率。\n\n副露率\n个人副露手数 ÷ 参与的手数。\n\n平均顺位\n各顺位场次 × 顺位之和 ÷ 总场次。\n\n番种记录\n记录累计出现次数，可重复计数，不是互斥占比。\n\n近期走势\n最近最多 20 场，按时间从旧到新。缺少明细的指标显示“—”。": "Périmètre statistique\nLes règles, le type de salle et les dates choisis s'appliquent aux résultats et à la liste des parties.\n\nTaux de victoire / d'écart perdant\nVictoires personnelles / écarts perdants ÷ mains jouées.\n\nPart des victoires sur pioche\nVictoires sur pioche ÷ victoires ; ce n'est pas un taux par main.\n\nTaux d'ouverture\nMains personnelles ouvertes ÷ mains jouées.\n\nPlace moyenne\nSomme des nombres de parties à chaque place × cette place ÷ nombre total de parties.\n\nCombinaisons\nOccurrences cumulées, avec chevauchements possibles ; proportions non exclusives.\n\nÉvolution récente\nJusqu'aux 20 dernières parties, de la plus ancienne à la plus récente. Les indicateurs sans détail affichent « — ».",
