    "国标麻将：高级场\n入场门槛：段位四段及以上\n场得pt：105\n场失pt：依照段位\n分配比例：+0.8+0.2-0.3-0.7\n对局设置：无提示 错和 战术鸣牌\n时间限制：20+5": "Mahjong MCR : salle avancé\nCondition d’accès : 4e dan ou supérieur\nPT gagnés par partie : 105\nPT perdus par partie : selon le rang\nRépartition : +0.8+0.2-0.3-0.7\nParamètres : sans indices, fausse victoire, appels tactiques\nTemps : 20+5",
    "国标麻将：MCRPL场\n入场门槛：Salasasa七段及以上或职业五段及以上并实名注册\n场得pt：135*0.49\n场失pt：依照段位*0.49\n分配比例：+0.8+0.2-0.3-0.7\n无提示 无指针提示 错和 战术鸣牌\n时间限制：20+5": "Mahjong MCR : salle MCRPL\nCondition d’accès : 7e dan Salasasa ou 5e dan professionnel ou supérieur, avec identité vérifiée\nPT gagnés par partie : 135*0.49\nPT perdus par partie : selon le rang*0.49\nRépartition : +0.8+0.2-0.3-0.7\nParamètres : sans indices ni indication du pointeur, fausse victoire, appels tactiques\nTemps : 20+5",
    "国标麻将：MCRPL场\n入场门槛：Salasasa七段及以上或职业五段及以上并实名注册\n场得pt：135*0.7\n场失pt：依照段位*0.7\n分配比例：+0.8+0.2-0.3-0.7\n对局设置：无提示 无指针提示 错和 战术鸣牌\n时间限制：20+5": "Mahjong MCR : salle MCRPL\nCondition d’accès : 7e dan Salasasa ou 5e dan professionnel ou supérieur, avec identité vérifiée\nPT gagnés par partie : 135*0.7\nPT perdus par partie : selon le rang*0.7\nRépartition : +0.8+0.2-0.3-0.7\nParamètres : sans indices ni indication du pointeur, fausse victoire, appels tactiques\nTemps : 20+5",
    "国标麻将：MCRPL场\n入场门槛：Salasasa七段及以上或职业五段及以上并实名注册\n场得pt：135\n场失pt：依照段位\n分配比例：+0.8+0.2-0.3-0.7\n对局设置：无提示 无指针提示 错和 战术鸣牌\n时间限制：20+5": "Mahjong MCR : salle MCRPL\nCondition d’accès : 7e dan Salasasa ou 5e dan professionnel ou supérieur, avec identité vérifiée\nPT gagnés par partie : 135\nPT perdus par partie : selon le rang\nRépartition : +0.8+0.2-0.3-0.7\nParamètres : sans indices ni indication du pointeur, fausse victoire, appels tactiques\nTemps : 20+5",
