    "点击下方牌面添加手牌；点击副露框后，只有能组成合法牌组的牌会高亮可点。 手牌 + 副露合计 12～14 张，所有牌必须分成 3 张及以上的合法牌组，无雀头。": "Cliquez sur les tuiles ci-dessous pour compléter la main. Après avoir sélectionné un groupe exposé, seules les tuiles permettant un groupe valide sont disponibles. La main et les groupes exposés doivent totaliser 12 à 14 tuiles, réparties en groupes valides d'au moins 3 tuiles, sans paire.",
