    "other/rule/inclued_rule/新编MCR.pdf": "other/rule/inclued_rule/新编MCR.pdf",
    "在 Salasasa 免费在线玩国标麻将 MCR，支持自动算番、段位匹配和牌谱复盘。浏览器 2D 无需下载，另有多规则客户端与麻将学习工具。": "Jouez gratuitement au mahjong MCR en ligne sur Salasasa, avec calcul automatique des fans, recherche d'adversaires par rang et relecture des parties. Le mode 2D dans le navigateur ne nécessite aucun téléchargement ; un client proposant plusieurs règles et des outils d'apprentissage du mahjong sont également disponibles.",
    "免费在线玩国标麻将 MCR | Salasasa": "Mahjong MCR en ligne gratuit | Salasasa",
    "在浏览器中免费进行国标麻将 MCR 对局，支持自动算番、段位匹配与牌谱复盘，界面提供简繁中文、英语、日语和法语。": "Jouez gratuitement au mahjong MCR dans votre navigateur, avec calcul automatique des fans, recherche d'adversaires par rang et relecture des parties. L'interface propose le chinois simplifié et traditionnel, l'anglais, le japonais et le français.",
    "东南西北": "Est, Sud, Ouest, Nord",
    "春夏秋冬 梅兰竹菊": "Printemps, été, automne, hiver ; prunier, orchidée, bambou, chrysanthème",
    "立直/古典用 round_index，国标/青雀用 current_round": "round_index en Riichi/classique, current_round en MCR/Qingque",
    "查看完整鸣谢名单": "Voir tous les remerciements",
    "申请人": "Demandeur",
    "北京麻将圈数": "Nombre de tours de Pékin",
    "混儿方式": "Mode hun'er",
    "局时储备（秒）": "Réserve de donne (secondes)",
    "步时（秒）": "Temps d'action (secondes)",
    "听牌提示": "Indication des attentes",
    "剩余张数提示": "Indication des tuiles restantes",
    "136张无花牌，0翻可和；吃碰明杠后仅可自摸，打出混儿后本局不可和牌。庄家和牌连庄，其余轮庄。": "136 tuiles sans fleurs, victoire à 0 fan possible. Après chow, pung ou kong exposé, seule la victoire sur pioche est permise. Écarter un hun'er interdit de gagner pour cette donne. Le donneur se maintient s'il gagne ; sinon, il change.",
    "可选规则变体（默认关闭）": "Variantes facultatives (désactivées par défaut)",
    "每张不按本体使用的混儿减1翻，最低保留1翻；原本0翻的和牌仍按0翻结算。": "Chaque hun'er utilisé comme une autre tuile retire 1 fan, avec un minimum de 1 fan ; une victoire valant initialement 0 fan reste à 0 fan.",
    "阅读北京麻将（吃碰提）完整规则与变体说明": "Lire les règles complètes et variantes du mahjong de Pékin (Chi Peng Ti)",
    "长春 ·": "Changchun ·",
    "末张单放：": "Dernière tuile isolée :",
    "应付": "À payer",
    "，由座位": ", par la place",
    "包庄": "Responsabilité du donneur",
    "MIL 2024：136张、十三张手牌，三门带幺九，可吃碰杠和报听。一条仅可在特殊杠中代牌；报听后看宝，六番封顶。三张特殊杠首次不补牌，以后每加一张补一张。": "MIL 2024 : 136 tuiles, main de treize tuiles, trois familles avec extrémités et honneurs ; chow, pung, kong et annonce d'attente possibles. Le un de bambou ne remplace une tuile que dans un kong particulier. La tuile trésor est consultée après annonce d'attente ; plafond de six fans. Le premier kong particulier de trois tuiles n'est pas remplacé ; chaque tuile ajoutée ensuite donne un remplacement.",
    "有效申请后可在5秒内以更高优先级抢断；机器人入座自动关闭": "Une demande valide peut être interrompue par une action prioritaire pendant 5 secondes ; désactivé automatiquement avec un robot",
    "阅读 MIL 长春规则书": "Lire le règlement MIL de Changchun",
