    "骰子": "Dés",
    "开杠补牌": "Remplacement après kong",
    "可用牌不足，本次未补牌": "Pas assez de tuiles ; aucun remplacement cette fois",
    "鸟牌（原位翻开）": "Oiseaux (retournés sur place)",
    "{count}大胡封顶（鸟另计）": "Plafond de {count} grandes victoires (oiseaux séparés)",
    "{count}分封顶（含鸟）": "Plafond de {count} points (oiseaux inclus)",
    "开杠后按骰子位置公开补牌；卡摸仅限制小胡点和。封顶按每名和牌者、每名付款者计算，同批多次和牌累计计入封顶。": "Après kong, les remplacements sont révélés selon les positions des dés. Kamo limite uniquement les petites victoires sur écart. Le plafond s'applique à chaque gagnant et chaque payeur ; les victoires multiples du même lot y sont cumulées.",
    "开局有2秒可选择全桌不换；换完一轮后可选择再换一轮，最多两轮。每轮选六张、最多两种花色；三种花色失去和牌资格。固定四张开杠、双鸟、小胡2分、大胡8分起、不封顶。": "Au début, la table dispose de 2 secondes pour choisir de ne pas échanger. Après un premier échange, un second peut être choisi, avec deux tours au maximum. Chaque tour échange six tuiles d'au plus deux familles ; trois familles font perdre le droit de gagner. Quatre tuiles après kong, deux oiseaux, petite victoire à 2 points, grande à partir de 8, sans plafond.",
    "经典双鸟": "Deux oiseaux classiques",
    "换牌时间（秒）": "Temps d'échange (secondes)",
    "社群二维码": "QR code de la communauté",
    "裁切标题图片": "Recadrer l'image de titre",
    "拖动图片调整位置，滚轮或滑块缩放。裁切比例与侧栏封面一致（约 2.2:1）。": "Déplacez l'image et zoomez avec la molette ou le curseur. Le rapport correspond à la couverture latérale (environ 2.2:1).",
    "缩放": "Zoom",
    "确认裁切并上传": "Confirmer le recadrage et importer",
    "夺彩子规则": "Variante Duocai",
    "对局形式": "Format de partie",
    "起始与返点均为40000点，顺位点为0；每副144张，包含8张不同赖子。两副牌组交替使用。": "Départ et référence finale à 40000 points, sans points de classement ; 144 tuiles par donne, dont 8 jokers différents. Deux jeux de tuiles alternent.",
    "阅读夺彩麻将规则书与赖子图鉴": "Lire les règles Duocai et le catalogue des jokers",
    "清空全部": "Tout vider",
    "四家均预置 13 张手牌、8 张固定牌墙，另设 24 张公共牌墙。庄家开牌首摸取自固定墙；一家摸空后，剩余固定牌按东南西北接到公共墙前。": "Chaque joueur reçoit 13 tuiles initiales et un mur fixe de 8 tuiles ; un mur commun de 24 tuiles est ajouté. Le donneur prend sa première pioche dans son mur fixe. Dès qu'un joueur a épuisé le sien, les murs fixes restants sont placés devant le mur commun dans l'ordre Est, Sud, Ouest, Nord.",
    "四家均预置 13 张手牌、14 张个人牌墙。庄家开牌首摸取自个人牌墙。无公共牌墙，不预先把庄家第一张摸牌放入手牌。": "Chaque joueur reçoit 13 tuiles initiales et un mur personnel de 14 tuiles. Le donneur prend sa première pioche dans son mur personnel. Aucun mur commun ; la première pioche du donneur n'est pas placée à l'avance dans sa main.",
    "副：": "Donne :",
