    "勾选 4 名玩家后，可在确认组桌时选择默认配置或预设。组桌后进入房间，不自动开局。": "Cochez 4 joueurs, puis choisissez la configuration par défaut ou un préréglage à la confirmation. Les joueurs entrent dans la salle, sans démarrage automatique.",
