    "在线玩家按准备时间依次匹配，凑够 4 人自动组桌并开局。使用所选配置的最新设置，正在进行的对局不受修改影响。": "Les joueurs en ligne sont appariés dans l'ordre de préparation. Dès qu'ils sont 4, une table est créée et démarre avec la dernière version de la configuration choisie. Les modifications n'affectent pas les parties en cours.",
