    "起和点数": "Minimum de points pour gagner",
    "只允许碰彩虹，不允许普通碰牌。每位玩家每局最多补牌两次。无色牌可组成对子或同色顺子，不能组成刻子或彩虹。": "Seuls les pungs arc-en-ciel sont autorisés, pas les pungs ordinaires. Chaque joueur peut remplacer des tuiles deux fois au maximum par donne. Les tuiles incolores peuvent former des paires ou des suites de même couleur, mais pas de pungs ni d'arcs-en-ciel.",
    "阅读完整规则书": "Lire le règlement complet",
