    "和牌张按": "Tuile gagnante selon",
    "MIL 2024：112张、十三张手牌，红中为万能牌，仅可自摸；可碰杠，不吃。最高四番，和牌后扎两鸟，流局退杠。": "MIL 2024 : 112 tuiles, main de treize tuiles, dragon rouge joker, victoire sur pioche uniquement ; pungs et kongs autorisés, chows interdits. Plafond de quatre fans, deux oiseaux tirés après victoire, remboursement des kongs sur donne nulle.",
    "阅读 MIL 红中规则书": "Lire le règlement MIL Dragon rouge",
    "九江麻将是九江地区一个没落的麻将规则，目前九江地区通行红中麻将，本规则是芋蔗凭借小时候的记忆和一定程度上的改良复现的一种失传规则，如发现任何问题或者能够提供九江麻将的资料的玩家可以联系Q2264033554": "Le mahjong de Jiujiang est une règle locale tombée en désuétude, remplacée aujourd'hui par le mahjong au dragon rouge. Yuzhe l'a reconstituée à partir de ses souvenirs d'enfance avec quelques améliorations. Pour signaler un problème ou fournir des documents sur cette règle, contactez Q2264033554.",
    "下载九江麻将规则书": "Télécharger les règles de Jiujiang",
    "回复": "Répondre",
    "加载回复…": "Chargement des réponses…",
    "暂无回复": "Aucune réponse",
    "写下回复…": "Écrivez une réponse…",
    "传统84张，东南西三席，5番起和。飞可作百搭或当花；花套与杠即时结算，和牌后另比输家花分与三家飞牌。": "Traditionnel à 84 tuiles, trois places Est, Sud et Ouest, minimum de 5 fans. Fei peut servir de joker ou de fleur. Séries de fleurs et kongs sont payés immédiatement ; après victoire, on compare aussi les points de fleurs des perdants et les fei des trois joueurs.",
