    "山西麻将 · MIL试行2023版。136张、十三张手牌、无花无癞子；须暗扣报听，有和必和，和牌时结杠。": "Shanxi · MIL provisoire 2023. 136 tuiles, main de treize tuiles, sans fleurs ni jokers. Annonce d'attente avec tuile couchée face cachée obligatoire ; toute victoire doit être prise. Les kongs sont réglés à la victoire.",
    "局时是每局额外思考储备，默认20秒；每次操作先使用步时，默认5秒。零局时只使用步时。": "Le temps de donne est une réserve de réflexion supplémentaire, de 20 secondes par défaut. Chaque action utilise d'abord son temps de base, de 5 secondes par défaut. À zéro réserve, seul le temps d'action est utilisé.",
