    "阅读温州 MIL 2024 规则书": "Lire le règlement Wenzhou MIL 2024",
    "MIL 2025：136张，皮癞单张杠；必须开口，逐家六番起和。末四张只能自摸或过，七皮、十杠途中结算，轮庄。鸣牌响应为3秒。": "MIL 2025 : 136 tuiles, kongs de peau/joker à une tuile ; main ouverte obligatoire, minimum de six fans calculé par adversaire. Sur les quatre dernières tuiles, gagner sur pioche ou passer uniquement. Sept Peaux et Dix Kongs sont décomptés en cours de donne ; le donneur change. Délai d'appel : 3 secondes.",
    "阅读 MIL 武汉规则书": "Lire le règlement MIL de Wuhan",
