    "庄家也只预置 13 张，开牌时再从自己的牌墙头摸一张。东南西北方位固定，庄家依次轮转。": "Le donneur reçoit aussi seulement 13 tuiles initiales et pioche ensuite au début de son mur. Les positions Est, Sud, Ouest et Nord restent fixes ; le donneur tourne.",
    "牌山类型": "Type de mur",
    "1–128 个字符的文本种子": "Graine textuelle de 1 à 128 caractères",
    "一个种子生成整场牌山。相同规则、花牌设置、局数和种子生成相同的手牌与牌山。": "Une graine génère tous les murs de la partie. À règles, fleurs, nombre de donnes et graine identiques, les mains et les murs sont identiques.",
    "编辑各局牌山": "Modifier le mur de chaque donne",
