    "分享美术资源规约": "Règlement du partage de ressources graphiques",
    "上传内容须由你拥有版权，或取得明确允许非商业使用和公开分享的许可证。": "Vous devez détenir les droits sur le contenu importé, ou une licence autorisant explicitement son utilisation non commerciale et son partage public.",
    "没有版权或许可证的资源只能私下使用，不能上传到平台分享站。": "Les ressources sans droits ni licence ne peuvent être utilisées qu'en privé, sans importation sur le site de partage.",
