    "修改": "Modifier",
    "查看已解除锁定的密钥、创建时间、解锁时间和关联对局。": "Consultez les clés déverrouillées, leurs dates de création et de déverrouillage, ainsi que leurs parties.",
    "创建复式密钥 →": "Créer une clé duplicate →",
    "输入复式密钥；留空查看最近解除锁定的密钥": "Saisissez une clé duplicate ; laissez vide pour les dernières clés déverrouillées",
    "锁定的密钥不公开。解除锁定后可在这里查询，且不能重新锁定。复式对局不保存本地牌谱。": "Les clés verrouillées ne sont pas publiques. Après déverrouillage, elles sont consultables ici et ne peuvent plus être verrouillées. Les parties duplicate n'ont pas de relevé local.",
    "创建者 / 所属赛事": "Créateur / compétition",
