    "再来一局": "Rejouer",
    "点击下方牌面添加手牌；点击副露框后，只有能组成合法牌组的牌会高亮可点。 手牌 + 副露合计最多 14 张，所有牌必须分成 3 张及以上的合法牌组，无雀头。 自摸支持连续加杠预测；手牌为空时也可输入副露，查看可摸入的和牌张。": "Cliquez sur les tuiles ci-dessous pour les ajouter à la main. Après sélection d'un cadre de groupe exposé, seules les tuiles permettant un groupe valide sont actives. Main et groupes exposés : 14 tuiles au maximum, toutes réparties en groupes valides d'au moins 3 tuiles, sans paire. La victoire sur pioche permet de prévoir les kongs ajoutés successifs. Même avec une main vide, saisissez les groupes exposés pour voir les pioches gagnantes.",
    "输入手牌或副露后计算和牌与预测": "Saisissez la main ou les groupes exposés pour calculer les victoires et prévisions",
    "加杠顺序": "Ordre des kongs ajoutés",
    "加入副露 #": "Ajouter au groupe exposé #",
    "当前牌型未成和牌；可查看下方摸入一张后的预测。": "La main actuelle n'est pas gagnante ; consultez les prévisions après une pioche ci-dessous.",
    "摸牌后的和牌预测（": "Victoires prévues après pioche (",
    "种）": "types)",
    "“仅自摸”需摸入后按顺序加杠；其他玩家的弃牌不能用于这种和法。展开查看加杠步骤与最终牌型。": "« Sur pioche uniquement » nécessite une pioche puis des kongs ajoutés dans l'ordre ; un écart adverse ne permet pas cette victoire. Développez pour voir les étapes et la forme finale.",
    "仅自摸 ·": "Sur pioche uniquement ·",
    "捉和": "Victoire sur écart",
    "分 · 自摸": "points · Sur pioche",
    "仅自摸：": "Sur pioche uniquement :",
    "；和牌": " ; victoire",
    "12/13 张显示向听与进张效率，14 张显示切牌效率。 已和牌仍会列出可继续扩展的进张；一向听、两向听、三向听及以上都会计算能减少向听的进张。 每种牌只有一张。输入为空时随机生成 14 张。计算在浏览器本地完成。": "Avec 12/13 tuiles, affiche le shanten et l'efficacité des tuiles utiles ; avec 14, l'efficacité des écarts. Même une main gagnante affiche les tuiles permettant de l'étendre. À un, deux, trois shanten ou davantage, les tuiles réduisant le shanten sont calculées. Chaque tuile n'existe qu'en un exemplaire. Une saisie vide génère 14 tuiles aléatoires. Le calcul s'effectue localement dans le navigateur.",
    "如 AX1 AX2 AX3 BX4 BX5 BX6": "Ex. AX1 AX2 AX3 BX4 BX5 BX6",
